import {
  BIND_PENDING_HOLDER,
  claimChatBind,
  journalWrite,
  newLocalRecord,
  releaseChatBind,
  UNBOUND_DESTINATION,
  type EntityDestination,
  type LocalFirstChange,
  type LocalFirstStore,
  type LocalFirstTransaction,
  type LocalRecord,
} from '@builderforce/local-first';
import type { PriceBook } from '@builderforce/model-catalog';
import { summarizeTranscript, type SummaryCompletion } from '@seanhogg/builderforce-memory/working';
import { combineSpendSavings, type SpendSavingsSummary } from '@builderforce/spend-contract';
import type { BrainPersistenceAdapter } from './config';
import { slotKeyedRows } from './keyedRows';
import type { BrainChat, BrainMessage } from './types';
import { transcriptSeedOf } from './transcriptSeed';
import { boundServerId } from './localChat/chatIdentity';
import {
  chatMessageRecords,
  chatMessagesInOrder,
  chatRecordById,
  chatsMessagesInOrder,
  messageRecordById,
  scanChatMessages,
  scanLive,
  type ChatValue,
  type MessageValue,
} from './localChat/records';
import { importedUsageIds, ledgerSpend, usageRowsByChat } from './localChat/ledgerSpend';
import type { RunUsageValue } from './localChat/usageLedger';
import { errorMessage } from './pageEngines/types';

/** A background server-spend seed that failed: the projection keeps the device's ledger
 *  figure, but the reason must not vanish (same shape as `pageEngines/engineFailure.ts`). */
function reportServerSpendFailure(error: unknown): void {
  console.warn(`BuilderForce chat spend: server spend read failed (${errorMessage(error)})`);
}

export interface LocalBrainPersistenceOptions {
  store: LocalFirstStore;
  deviceId: string;
  destination?: EntityDestination;
  /** Why "Consolidate" / "Fork" cannot run here — no {@link summarize} port. */
  summarizeUnavailable: string;
  /**
   * The model call a chat summary is written with (the ONE transcript summarizer,
   * `@seanhogg/builderforce-memory/working`). Omitted: summarizing reports
   * {@link summarizeUnavailable}.
   */
  summarize?: SummaryCompletion;
  /** Why a summary came back empty or failed (the model call errored). */
  summarizeFailed?: string;
  /**
   * The account destination chats bind into right now (PRD 36) — what `serverId` is
   * projected from. Omitted or undefined (signed out): every chat reads as unbound.
   */
  accountDestination?: () => EntityDestination | undefined;
  /**
   * The platform's spend for bound chats, by server id — the authoritative figure for
   * the calls the gateway served. Omitted, or failing: the device's own estimate stands.
   * Never awaited on a local read: an offline call can block for its whole timeout, so
   * the projection resolves from the synchronous {@link serverSpendSync} cache and this
   * port only seeds that cache (a result it has already cached resolves instantly).
   */
  serverSpend?: (serverIds: readonly number[]) => Promise<ReadonlyMap<number, SpendSavingsSummary>>;
  /**
   * The synchronous spend cache the async {@link serverSpend} fills. When it holds a
   * value the projection answers from it immediately; when it does not, the projection
   * proceeds from the local ledger and asks the async port to fill the cache for the
   * next read. Omitted: the projection never reaches for the server at all.
   */
  serverSpendSync?: () => ReadonlyMap<number, SpendSavingsSummary> | null;
  /** Bind a chat now (the host's chat identity). Omitted: the adapter offers no `bindChat`. */
  bindChat?: (chatId: number) => Promise<number | undefined>;
  /** The book a chat's own calls are priced with. Defaults to the bundled snapshot. */
  priceBook?: () => PriceBook;
  createObjectURL?: (file: File) => string;
  now?: () => Date;
  newId?: () => string;
}

const chatValue = (record: LocalRecord<ChatValue>): BrainChat => record.payload.chat;

/** A commit naming more message rows than this is not worth checking row by row: reload. */
const MESSAGE_ID_CHECK_LIMIT = 64;

/** A chat as its surfaces read it: its bound server id and its spend projected on. */
interface ProjectionInput {
  record: LocalRecord<ChatValue>;
  serverId: number | undefined;
  usage: readonly RunUsageValue[];
  /** The rows a sync import already put on the platform (bound chats only). */
  imported: ReadonlySet<string>;
}

export function createLocalBrainPersistence(options: LocalBrainPersistenceOptions): BrainPersistenceAdapter {
  const destination = options.destination ?? UNBOUND_DESTINATION;
  const now = options.now ?? (() => new Date());
  const newId = options.newId ?? (() => crypto.randomUUID());
  const blobs = new Map<string, string>();

  /** One chat's messages in `seq` order — read through the chat index, never every chat's rows. */
  const chatMessages = (chatId: number): Promise<BrainMessage[]> =>
    options.store.read((tx) => chatMessagesInOrder(tx, options.deviceId, chatId));
  const chatFor = async (tx: LocalFirstTransaction, id: number): Promise<LocalRecord<ChatValue>> => {
    const chat = await chatRecordById(tx, options.deviceId, id);
    if (!chat) throw new Error(`No such local chat: ${id}`);
    return chat;
  };
  /** One past the largest chat or message id — a scan, not a copy of every row. */
  const nextId = async (tx: LocalFirstTransaction): Promise<number> => {
    let highest = 0;
    await scanLive<ChatValue>(tx, 'chat', options.deviceId, (row) => { highest = Math.max(highest, row.payload.chat.id); });
    await scanLive<MessageValue>(tx, 'message', options.deviceId, (row) => { highest = Math.max(highest, row.payload.message.id); });
    return highest + 1;
  };
  /** Does this commit touch the chat's messages? Row ids are looked up (`get`), never scanned. */
  const touchesChatMessages = (chatId: number, change: LocalFirstChange): Promise<boolean> => {
    const ids = change.records.get('message');
    if (!ids || ids.size === 0) return Promise.resolve(false);
    if (ids.size > MESSAGE_ID_CHECK_LIMIT) return Promise.resolve(true);
    return options.store.read(async (tx) => {
      for (const id of ids) {
        const row = await tx.get<MessageValue>('message', id);
        // A row that is gone cannot be placed in a chat: assume it was this one's.
        if (!row || row.payload.chatId === chatId) return true;
      }
      return false;
    });
  };

  /** Read the chats' projection inputs in one pass: bindings and ledger rows. */
  const projectionInputs = async (tx: LocalFirstTransaction, rows: readonly LocalRecord<ChatValue>[]): Promise<ProjectionInput[]> => {
    const account = options.accountDestination?.();
    const usage = await usageRowsByChat(tx, options.deviceId, new Set(rows.map((record) => record.id)));
    return Promise.all(rows.map(async (record) => {
      const serverId = await boundServerId(tx, record.id, account);
      const chatUsage = usage.get(record.id) ?? [];
      return {
        record,
        serverId,
        usage: chatUsage,
        imported: serverId !== undefined && account ? await importedUsageIds(tx, chatUsage, account) : new Set<string>(),
      };
    }));
  };

  /**
   * The spend each chat shows (§3.2), answered from LOCAL state — never waiting on the
   * network. A spend read that is still in flight (or failed) resolves from the local
   * ledger; the server figure lands on the next read that arrives after it settles
   * (its result is cached, so that read is instant and correct).
   */
  const project = async (inputs: readonly ProjectionInput[]): Promise<BrainChat[]> => {
    const bound = inputs.flatMap((input) => (input.serverId !== undefined ? [input.serverId] : []));
    let server: ReadonlyMap<number, SpendSavingsSummary> | null = null;
    if (bound.length > 0 && options.serverSpend) {
      server = options.serverSpendSync?.() ?? null;
      // Cache miss: seed it in the background. Never awaited — an offline read must
      // not wait on the network; the next projection picks the figure up.
      if (!server) void options.serverSpend(bound).catch(reportServerSpendFailure);
    }
    return inputs.map(({ record, serverId, usage, imported }) => {
      const chat = chatValue(record);
      // The platform's figure covers the gateway's calls only when it HAS this chat; a
      // chat it could not report keeps the device's estimate of every call.
      const fromServer = serverId !== undefined ? server?.get(serverId) ?? null : null;
      const local = ledgerSpend(usage, {
        excludeGateway: fromServer !== null,
        imported,
        ...(options.priceBook ? { book: options.priceBook() } : {}),
      });
      const spend = fromServer && local ? combineSpendSavings(fromServer, local) : fromServer ?? local;
      return {
        ...chat,
        clientId: record.id,
        ...(serverId !== undefined ? { serverId } : {}),
        ...(spend ? { spend } : {}),
      };
    });
  };

  /**
   * One page of the chat list (archived or live), most recently updated first, projected.
   * The chats are scanned uncloned and only the page is copied — a list of 20 never copies
   * the whole history's chat rows, nor any other chat's ledger rows.
   */
  const listPage = async (archived: boolean, params?: { projectId?: string; limit?: number; offset?: number }): Promise<BrainChat[]> => {
    const inputs = await options.store.read(async (tx) => {
      const all: Readonly<LocalRecord<ChatValue>>[] = [];
      await scanLive<ChatValue>(tx, 'chat', options.deviceId, (row) => {
        if (archived ? row.payload.chat.isArchived !== true : row.payload.chat.isArchived) return;
        if (params?.projectId != null && String(row.payload.chat.projectId) !== params.projectId) return;
        all.push(row);
      });
      all.sort((a, b) => b.payload.chat.updatedAt.localeCompare(a.payload.chat.updatedAt) || b.payload.chat.id - a.payload.chat.id);
      const offset = params?.offset ?? 0;
      const page = params?.limit != null ? all.slice(offset, offset + params.limit) : all.slice(offset);
      return projectionInputs(tx, structuredClone(page) as LocalRecord<ChatValue>[]);
    });
    return project(inputs);
  };

  return {
    listChats: (params) => listPage(false, params),
    /**
     * The archived chats `listChats` hides — same projection, the rows where
     * `isArchived` is set, most recently updated first. The archive surface reads
     * through this; the live list never widens to include them.
     */
    listArchivedChats: (params) => listPage(true, params),
    async getChat(id) {
      const inputs = await options.store.read(async (tx) => projectionInputs(tx, [await chatFor(tx, id)]));
      return (await project(inputs))[0]!;
    },
    async createChat(body) {
      return options.store.transact(async (tx) => {
        const [id, clientId] = [await nextId(tx), newId()];
        const stamp = now().toISOString();
        const chat: BrainChat = {
          id,
          title: body.title ?? 'New chat',
          projectId: body.projectId ?? null,
          origin: 'local',
          capability: body.capability ?? null,
          mode: body.mode ?? null,
          originalRequest: body.originalRequest ?? null,
          createdAt: stamp,
          updatedAt: stamp,
        };
        const record = newLocalRecord<ChatValue>({
          id: clientId,
          entityType: 'chat',
          payload: { clientId, chat },
          deviceId: options.deviceId,
          destination,
          occurredAt: stamp,
        });
        await tx.put(record);
        await journalWrite(tx, record, 'create', { key: `chat:${clientId}` });
        // The caller will `identity.adopt` a server chat: hold the chat's import back from THIS
        // commit on, so no sync round sends it before adopt's own claim. adopt re-stamps the same
        // lease and releases it; it expires on its own if adopt never runs (`CHAT_BIND_LEASE_MS`).
        if (body.bindPending) await claimChatBind(tx, clientId, now(), BIND_PENDING_HOLDER);
        return chat;
      });
    },
    async updateChat(id, body) {
      return options.store.transact(async (tx) => {
        const current = await chatFor(tx, id);
        const chat = { ...current.payload.chat, ...body, updatedAt: now().toISOString() };
        const next: LocalRecord<ChatValue> = {
          ...current,
          version: current.version + 1,
          baseVersion: current.version,
          updatedAt: chat.updatedAt,
          payload: { ...current.payload, chat },
        };
        await tx.put(next, current.version);
        await journalWrite(tx, next, 'update', { key: `chat:${current.id}:v${next.version}` });
        return chat;
      });
    },
    async deleteChat(id) {
      return options.store.transact(async (tx) => {
        const chat = await chatFor(tx, id);
        const stamp = now().toISOString();
        const deleted = { ...chat, version: chat.version + 1, baseVersion: chat.version, deletedAt: stamp, updatedAt: stamp };
        const chatDeleteKey = `chat:${chat.id}:delete:v${deleted.version}`;
        await tx.put(deleted, chat.version);
        await journalWrite(tx, deleted, 'delete', { key: chatDeleteKey });
        // A deleted chat is never bound: a `createChat({ bindPending })` lease its caller abandoned
        // (its server create or adopt failed) must not hold the chat's journal back for its 120 s.
        await releaseChatBind(tx, chat.id, BIND_PENDING_HOLDER);
        const rows = await chatMessageRecords(tx, options.deviceId, id);
        for (const row of rows) {
          const tombstone = { ...row, version: row.version + 1, baseVersion: row.version, deletedAt: stamp, updatedAt: stamp };
          await tx.put(tombstone, row.version);
          await journalWrite(tx, tombstone, 'delete', {
            key: `message:${row.id}:delete:v${tombstone.version}`,
            dependsOn: [chatDeleteKey],
            chatClientId: chat.id,
          });
        }
        return {};
      });
    },
    /**
     * Archive, not destroy. Unlike `deleteChat` this does NOT tombstone the row
     * (which would lose the conversation's summary): it marks the chat archived
     * and keeps it, mirroring the server's `isArchived` flag. `listChats` hides
     * archived rows, so the chat leaves the list without being deleted.
     */
    async archiveChat(id) {
      return options.store.transact(async (tx) => {
        const current = await chatFor(tx, id);
        const stamp = now().toISOString();
        const chat = { ...current.payload.chat, isArchived: true, updatedAt: stamp };
        const next: LocalRecord<ChatValue> = {
          ...current,
          version: current.version + 1,
          baseVersion: current.version,
          updatedAt: stamp,
          payload: { ...current.payload, chat },
        };
        await tx.put(next, current.version);
        await journalWrite(tx, next, 'update', { key: `chat:${current.id}:archive:v${next.version}` });
        return { archived: true };
      });
    },
    async summarizeChat(chatId) {
      if (!options.summarize) return { error: options.summarizeUnavailable };
      // What the model would be seeded with — from the last consolidation, no step rows.
      const seed = transcriptSeedOf(await chatMessages(chatId)).messages;
      // Under two turns there is nothing to consolidate: an empty summary says so.
      if (seed.length < 2) return { summary: '' };
      const summary = await summarizeTranscript(options.summarize, seed);
      return summary ? { summary } : { error: options.summarizeFailed ?? options.summarizeUnavailable };
    },
    ...(options.bindChat ? { bindChat: options.bindChat } : {}),
    getMessages: (chatId, limit) => options.store.read((tx) => chatMessagesInOrder(tx, options.deviceId, chatId, limit)),
    /** Several chats' messages in ONE store read (one journal refresh), each through the chat index. */
    getMessagesForChats: (chatIds) => options.store.read((tx) => chatsMessagesInOrder(tx, options.deviceId, chatIds)),
    // Only a commit that touched THIS chat's message rows (or whose change is unknown) is
    // worth a reload: a step row in another chat, a usage row, a sync receipt is not.
    subscribeMessages: (chatId, onChanged) => options.store.subscribe((change) => {
      if (!change) {
        onChanged();
        return;
      }
      void touchesChatMessages(chatId, change)
        .then((touched) => { if (touched) onChanged(); })
        .catch(() => onChanged());
    }),
    async sendMessages(chatId, input) {
      return options.store.transact(async (tx) => {
        const chat = await chatFor(tx, chatId);
        const firstId = await nextId(tx);
        const stamp = now().toISOString();
        // A row sent again under the key it was saved with is the SAME row (`keyedRows.ts`): the saved one comes
        // back, nothing is written - the server's upsert on (chat, event_key), kept on the device. Scanned
        // without cloning: only the rows handed back below are copied.
        const known = new Map<string, BrainMessage>();
        let existing = 0;
        await scanChatMessages(tx, options.deviceId, chatId, (row) => {
          existing += 1;
          // Index order is unspecified: of two rows under one key, the later (`seq`) one is the saved one.
          const prior = known.get(row.payload.eventKey);
          if (!prior || row.payload.message.seq >= prior.seq) known.set(row.payload.eventKey, row.payload.message);
        });
        const results: BrainMessage[] = [];
        const added: BrainMessage[] = [];
        const keys: string[] = [];
        for (const slot of slotKeyedRows(input, (key) => known.get(key))) {
          if (slot.kind === 'known') {
            results.push(structuredClone(slot.prior));
            continue;
          }
          if (slot.kind === 'repeat') {
            results.push(results[slot.of]!);
            continue;
          }
          const message = slot.row;
          const row: BrainMessage = {
            id: firstId + added.length,
            role: message.role,
            content: message.content,
            metadata: message.metadata ?? null,
            seq: existing + added.length + 1,
            createdAt: stamp,
          };
          results.push(row);
          added.push(row);
          keys.push(slot.key ?? `message:${newId()}`);
        }
        for (const [index, message] of added.entries()) {
          const eventKey = keys[index]!;
          const clientId = newId();
          const record = newLocalRecord<MessageValue>({
            id: clientId,
            entityType: 'message',
            payload: { clientId, chatId, chatClientId: chat.id, eventKey, message },
            deviceId: options.deviceId,
            destination: chat.destination,
            occurredAt: stamp,
          });
          await tx.put(record);
          await journalWrite(tx, record, 'create', { key: eventKey, dependsOn: [`chat:${chat.id}`], chatClientId: chat.id });
        }
        if (added.length > 0) {
          const nextChat = { ...chat, version: chat.version + 1, updatedAt: stamp, payload: { ...chat.payload, chat: { ...chat.payload.chat, updatedAt: stamp } } };
          await tx.put(nextChat, chat.version);
        }
        return results;
      });
    },
    async setMessageFeedback(messageId, feedback, context) {
      return options.store.transact(async (tx) => {
        const row = await messageRecordById(tx, options.deviceId, messageId, context?.chatId ?? undefined);
        if (!row) return {};
        const metadata = JSON.parse(row.payload.message.metadata ?? '{}') as Record<string, unknown>;
        metadata.feedback = feedback;
        if (context?.toolName) metadata.feedbackTool = context.toolName;
        const next = {
          ...row,
          version: row.version + 1,
          baseVersion: row.version,
          updatedAt: now().toISOString(),
          payload: { ...row.payload, message: { ...row.payload.message, metadata: JSON.stringify(metadata) } },
        };
        await tx.put(next, row.version);
        await journalWrite(tx, next, 'update', { key: `message:${row.id}:feedback:v${next.version}`, chatClientId: row.payload.chatClientId });
        return {};
      });
    },
    async upload(file) {
      const key = newId();
      const url = options.createObjectURL?.(file);
      if (url) blobs.set(key, url);
      await options.store.transact(async (tx) => {
        const record = newLocalRecord({
          id: key,
          entityType: 'attachment-manifest',
          payload: { key, name: file.name, type: file.type, size: file.size },
          deviceId: options.deviceId,
          destination,
        });
        await tx.put(record);
        await journalWrite(tx, record, 'create', { key: `attachment:${key}` });
      });
      return { key, name: file.name, type: file.type };
    },
    uploadUrl: (key) => blobs.get(key) ?? '',
  };
}
