/**
 * What a Brain run still OWES when its model stops calling tools, as the rungs the one agent's stall ladder walks (PRD 35
 * §4 WS4: "stop hook, ship gate, review gate, restated reply" and the delegation recovery). The agent owns the MECHANICS -
 * re-state, count, fall through - and this supplies which rungs hold and the words each says. The gates are the SAME data the
 * Brain's own final-answer hook asks (`runStore/deliveryGates.ts`); the workspace stop hook is `stopHooks.ts`. Pure over the
 * run's facts; nothing here iterates.
 */

import { liftProseAskUser, replayTextOf } from '@builderforce/agent-loop';
import type { DeliveryLedger, DeliveryTurn, LadderRung } from '@builderforce/agent-run';
import { askStopHook, MAX_STOP_HOOK_ROUNDS } from '../stopHooks';
import { deliveryGates, PENDING_NARRATION_GATE } from '../runStore/deliveryGates';

import { emit, nowIso, pushTrace } from '../runStore/runCells';
import { persistReply, type BrainRunContext } from '../runStore/brainRunContext';
import { persistMidTurnText } from '../runStore/turnPersistence';
import type { LastTurn } from './brainTurn';
import { noteFinishSkipsGates } from './finishSkipsGates';
import { transportRetryTrace } from '../runPolicyTraces';

/** The stop hook's counter key; the other rungs are `deliveryGates.ts`'s. */
const STOP_HOOK_RUNG = 'brain.stop_hook';

export function brainDeliveryLedger(run: BrainRunContext, last: LastTurn): DeliveryLedger {
  const { c, req, userRequest, canAskUser } = run;
  const { runTool } = req;
  // A rung's step is written once the turn it is about has been saved (`sentBack`): the agent saves the sent-back text, then the ledger says why.
  const held: Array<() => void> = [];
  const note = (label: string, result: string, args: Record<string, unknown> = {}): void => {
    const step = { ts: nowIso(), category: 'message' as const, label, args: { step: last.step, ...args }, result };
    held.push(() => pushTrace(c, step));
  };
  // A model that asked its question in prose instead of calling `ask_user` still gets the clickable card.
  // The agent holds a turn as it is replayed (the reply, else its reasoning as plain text); the settled message is the turn as the model
  // wrote it, reasoning block and all, which the person can open (`canonicalTurnText`).
  const asWritten = (content: string): string => (last.result && replayTextOf(last.result.text).trim() === content.trim() ? last.result.text : content);
  const accept = (content: string): string => {
    const full = asWritten(content).trim();
    return (canAskUser ? liftProseAskUser(full) : full) || 'No response.';
  };
  /** The workspace stop hook's directive for this turn, or null. */
  const askStop = (): Promise<string | null> =>
    askStopHook(req.onStop, { codeChanged: c.codeChanged, touchedFiles: c.touchedFiles, requestText: userRequest, round: run.stopHookRounds });
  /** A finishing run's answer was taken without asking the stop hook or any gate: say so, once (`finishSkipsGates.ts`). */
  const skippedByFinish = (content: string): Promise<void> =>
    noteFinishSkipsGates(run, last.step, content, { id: STOP_HOOK_RUNG, applies: async () => (await askStop()) !== null });
  return {
    providerFailure: {
      rerouted({ step, outcome, message }) {
        last.abandonedFailure = undefined;
        pushTrace(c, transportRetryTrace(nowIso(), step, outcome, message));
      },
      abandoned() {
        last.abandonedFailure?.();
        last.abandonedFailure = undefined;
      },
    },
    // A host that cannot run a tool judges no stall at all (the rungs are none): the turn IS the answer.
    owns: { settle: true, ...(runTool ? {} : { narration: true as const }) },
    // The Brain's stall order and wording (the stall policy's options below): a narrating turn is re-prompted before any rung, a model that
    // spent its budget is failed over (reading the nudge alone) or stopped only once every rung is clear, the rungs' directives are the
    // person's rows, and the stall is judged against the menu the turn advertised. The closing answer after a failure streak is the
    // agent's own forced no-tools turn, with a prompt that names the streak (`failureSynthesis`); no other ending asks for one.
    stall: { narrationFirst: true, steersFirst: true, nudgeAs: 'user', failoverNudgeOnly: true, menu: true, quoteEmpty: true, runWideBudget: true, failureSynthesis: true },
    // The stall judgement and the gates read the model's own words, reasoning included (`last.result.text`).
    judged: (content) => last.result?.text ?? content,
    // A turn sent back keeps what the person watched stream in: as its own block, or - a model that stalled out and was handed
    // over - as the reply it was (the nudge-and-requeue and failover rungs).
    async sentBack({ kept }) {
      const result = last.result;
      if (!result) return;
      if (kept === 'settled') last.settled = await persistReply(run, accept(result.text), result, last.requested);
      else if (kept === 'reply') await persistReply(run, accept(result.text), result, last.requested);
      else await persistMidTurnText(run.chatId, c, run.req.persistence, result, last.requested);
      c.streamingText = '';
      emit(c);
      for (const write of held.splice(0)) write();
    },
    accept,
    // A FINISHING run ("make no more changes and run nothing") is never sent back for more work: the agent asks no rung of its record
    // turns or its final report (`PolicyContext.finishing`) and tells the ledger here what that skipped, once.
    async finalAccepted({ content }) {
      if (runTool) await skippedByFinish(content);
    },
    async rungs(turn: DeliveryTurn): Promise<readonly LadderRung[]> {
      // A host that cannot run a tool owes nothing: the turn IS the answer.
      if (!runTool) return [];
      // A rung that sends a would-be final answer back: should the re-prompt then fail on the provider, the run keeps that answer (`brainSettle.ts`).
      const sentBackAnswer = (): void => { last.sentBackAnswer = { step: last.step }; };
      // The WORKSPACE's end-of-run directives, asked before the ship gate so whatever they make the run do is part of the change that ships.
      const stopNudge = await askStop();
      // A blocked finish that already wrote files continues on the review model; a QUICK run has no verify stage.
      const verifiable = c.codeChanged && !run.route.skipsVerify;
      const stopHook: LadderRung = {
        id: STOP_HOOK_RUNG, applies: !!stopNudge, restate: Array<string>(MAX_STOP_HOOK_ROUNDS).fill(stopNudge ?? ''), free: MAX_STOP_HOOK_ROUNDS, quote: true, spent: 'fall', entersVerify: verifiable,
        onRestate: () => {
          sentBackAnswer();
          run.stopHookRounds += 1;
          note('loop.stop_hook', `A workspace stop hook held the run for another turn: ${(stopNudge ?? '').slice(0, 200)}`, { round: run.stopHookRounds });
        },
      };
      const gates: LadderRung[] = deliveryGates(run).map((gate) => ({
        id: gate.id,
        applies: gate.applies(turn.content),
        restate: [gate.nudge()],
        quote: true,
        spent: 'fall',
        entersVerify: gate.entersVerify && verifiable,
        onRestate: () => {
          // A narration while a call is still running is not an answer the run could settle on.
          if (gate.id !== PENDING_NARRATION_GATE) sentBackAnswer();
          gate.spend();
          note(gate.trace.label, gate.trace.result, gate.trace.args());
        },
      }));
      return [stopHook, ...gates];
    },
  };
}
