/**
 * gatherChatDiagnostics — the one ASSEMBLER behind every "Copy diagnostics" report.
 *
 * {@link formatChatDiagnostics} has always been shared, so the two surfaces RENDER
 * identically. What was not shared was the step before it: each host built its own
 * {@link ChatDiagnosticsData} inline — the VS Code webview inside `App.tsx`'s
 * `copyTranscript` callback, the web app inside `BrainPanel.tsx`'s `captureExecution`,
 * the headless probe inside `probe.ts`. Three assemblies of one object, and they
 * drifted exactly as three copies do: the probe's report silently omitted
 * `projectName`, `chatVisibility`, `modelFunding` and `extensionVersion`, because those
 * four were assembled from React state the probe has no access to. A report that is
 * "equivalent" to a Copy click is not the same thing as one that is byte-identical to
 * it, and only the second can be used to reproduce a user's capture.
 *
 * So the assembly lives here, host-agnostic: the caller supplies the facts it already
 * holds and READERS for the facts it has to fetch, and this owns the parts that must
 * not be re-derived — running every read concurrently, degrading each one
 * independently to null/[], reading the observed per-turn tool exposure off the trace,
 * and classifying which purse funds the model.
 *
 * Pure of fetch, DOM and React: the readers are injected, so the same function serves
 * a webview, a Next.js client component and a Node CLI.
 */

import type { SpendSavingsSummary } from './spendSavings';
import { classifyModelFunding, type ChatDiagnosticsAccount, type ChatDiagnosticsData, type ChatDiagnosticsEvermind, type ChatDiagnosticsMeter, type ChatDiagnosticsRuns } from './chatDiagnostics';
import { toolExposureInTrace } from './toolExposure';
import { accountUsedInTrace, type BrainTraceEvent } from './brainTriage';
import { sessionShippedInTrace, sessionWorkInTrace } from './staffingSummary';
import { traceWithPersistedSteps } from './persistedSteps';
import type { BrainMessage } from './types';
import { publishHoldFromPersonTurns, type PublishHold } from './runStore/publishHold';
import { isInjectedTurnMetadata } from './injectedTurn';
import { isShipMode, narrowByHold, shipPolicyOf, type ShipPolicySource } from '@builderforce/run-guards';
import { isStepMessage } from './types';
import { selectPendingAskUser } from '@builderforce/agent-loop';
import { entityIdsOf, toolResultRecord } from './toolResultRecord';
import { isTicketWriteTool } from './ticketToolVocabulary';
import { isFailedToolResult } from './toolFailure';

/** The `/api/consumption` snapshot, structurally — each host has its own named type
 *  for it, and they agree on exactly these fields. */
export interface ChatDiagnosticsPlanSnapshot {
  period: { start: string; resetsAt: string };
  plan: { effective: string; billingStatus: string };
  meters: ChatDiagnosticsMeter[];
  /** Every limit is lifted because the CALLER is a superadmin — not because the plan
   *  grants it. Optional: an older API does not send it. */
  limitsLiftedBySuperadmin?: boolean;
  /** Spent vs saved over the last 30 days. Optional: an older API does not send it. */
  spendSavings?: SpendSavingsSummary | null;
}

/** The `/llm/v1/models` surface, structurally — enough to classify funding and to
 *  count what the plan pool offers. */
export interface ChatDiagnosticsModelSurface {
  data?: Array<{ id?: string }>;
  byo?: { providers?: string[]; models?: Array<{ id?: string; vendor?: string }> };
  canUsePremiumModels?: boolean;
}

/** The `/api/projects/:id/evermind/contributions` head, structurally. */
export interface ChatDiagnosticsEvermindHead {
  version: number;
  mode: string;
  inferenceEnabled?: boolean;
  teacherModel?: string | null;
  contributions?: number;
  pending?: number;
  lastLearnedAt?: string | null;
}

/** The minimum of a message this needs: the last assistant turn's learn outcome.
 *  Structural on purpose so a host can pass its own message array unchanged. */
export interface ChatDiagnosticsMessageLike {
  role: string;
  evermindLearn?: { learned: boolean; version: number; reason?: string | null } | null;
  /** The turn's text — read to re-derive the publish hold from the PERSON's own words.
   *  Optional: a surface that cannot supply it simply reports no hold line. */
  content?: string | null;
  /** The persisted row's metadata (JSON string or object) — an injected user turn (`injectedTurn.ts`) is not the person's. */
  metadata?: unknown;
}

/**
 * Everything the report needs, split into what the host KNOWS and what it must READ.
 *
 * Every reader is optional and best-effort: an omitted one is simply "not gathered"
 * and a rejecting one degrades to null/[]. That is deliberate — a diagnostics capture
 * whose whole point is to explain a broken chat must never itself fail because one of
 * the endpoints it asks about is the broken one.
 */
export interface ChatDiagnosticsSources {
  /** Which surface produced the capture ('Web' | 'VS Code (VSIX)' | …). */
  surface: string;
  chatId?: number | null;
  chatTitle?: string | null;
  /** 'shared' | 'locked'. */
  chatVisibility?: string | null;
  /** The chat's MODE ('chat' | 'work') — what the run was obliged to do, which is what
   *  decides whether "planned it and stopped" is correct behaviour or a failed execution. */
  mode?: string | null;
  /** The CHAT's own project — what the learn gate keys on. */
  projectId?: number | null;
  projectName?: string | null;
  /** The project the surrounding UI currently has SELECTED — `null` when none is.
   *  Always reported, so "nothing selected" stays distinguishable from "selected but
   *  the chat never adopted it" (see `ChatDiagnosticsData.selectedProjectId`). */
  selectedProjectId?: number | null;
  /** Display name for {@link selectedProjectId}, when the host holds one. */
  selectedProjectName?: string | null;
  tenantId?: number | string | null;
  userId?: string | null;
  /** The tenant the surrounding UI currently ACTS AS (its selected workspace), when the
   *  surface tracks one — distinct from {@link tenantId}, which is decoded from the token's
   *  own claims. A mismatch between the two is what makes a platform write die with 403
   *  "Project belongs to a different workspace" (a parked re-scope hands back another
   *  tenant's token while the workspace selection still points elsewhere), so the report
   *  names both. Absent when the surface does not track a separate workspace selection. */
  workspaceTenantId?: number | string | null;
  /** The caller's workspace role, when the host already knows it (from its own stored
   *  tenant/token — NEVER a new read: a capture must add no round trips). */
  role?: string | null;
  /** The transcript — read for the newest assistant turn's learn outcome and the
   *  message/step counts. */
  messages?: readonly ChatDiagnosticsMessageLike[];
  /** Where the full dialogue is stored on this surface (a file path, a chat URL). */
  historyLocation?: string | null;
  /** This chat's dollar rollup (`BrainChat.spend`). Null when the server has none yet. */
  spend?: import('./spendSavings').SpendSavingsSummary | null;
  /** The live tool registry the conversation runs on, and why it might be short. */
  tools?: { count: number; error?: string | null; loading?: boolean };
  /** The run's trace, so the report states the tools the model was ACTUALLY handed
   *  per turn rather than a ceiling derived from the registry size. */
  trace?: readonly BrainTraceEvent[];
  /** The model pinned for this chat, or null when the gateway routes per turn. */
  model?: string | null;
  /** The model surface the pickers already loaded — reused, never re-fetched. */
  modelSurface?: ChatDiagnosticsModelSurface | null;
  /** The build that produced the capture (extension version / web app version). */
  uiVersion?: string | null;
  /** Short SOURCE HASH of the client artifact — the identity `uiVersion` cannot carry
   *  (two artifacts can share a version and differ in code). `"dev"` when unbundled. */
  uiBuildId?: string | null;
  /** ISO timestamp the client artifact was built. */
  uiBuiltAt?: string | null;
  /** Source hash of the WEBVIEW bundle, when the surface ships one separately from its
   *  host. Both halves of the VS Code extension travel in one `.vsix`, so these match in
   *  a released install — a MISMATCH is the case that used to be invisible, and the one
   *  that made "is the host older than the version it reports?" unanswerable. */
  webviewBuildId?: string | null;
  webviewBuiltAt?: string | null;
  /** Whether this machine can run the POSIX git scripts (`git_sync_latest` / `undo` /
   *  `redo`). Absent on a surface with no local shell. */
  posixShell?: string | null;
  /** The gateway this surface is talking to. */
  baseUrl?: string | null;

  /** Resolve the chat project's NAME when the host does not already hold it (the two
   *  UI surfaces read it from a loaded project list; the headless probe has none).
   *  Wins over the static `projectName` above when it answers. */
  readProjectName?: () => Promise<string | null>;
  readAgents?: () => Promise<Array<{ agentRef: string; role: string; name?: string; builtinKind?: string | null }>>;
  readTickets?: () => Promise<Array<{ kind: string; ref: string; label?: string; linkType?: string; status?: string }>>;
  /**
   * The chat's EXECUTION HISTORY — what actually ran, and who started it.
   *
   * Optional, and its absence is reported as "not gathered" rather than "nothing ran":
   * those are opposite findings, and a surface that has not adopted the read must not
   * be able to assert the stronger one by omission.
   */
  readRuns?: () => Promise<ChatDiagnosticsRuns | null>;
  readEvermind?: () => Promise<ChatDiagnosticsEvermindHead | null>;
  readPlan?: () => Promise<ChatDiagnosticsPlanSnapshot | null>;
  /** Resolve the deployed API version — bounded + session-cached by
   *  `fetchApiVersionVia`, which every host reaches it through. */
  readApiVersion?: () => Promise<string | null>;
}

const SHIP_SOURCES: ReadonlySet<string> = new Set<ShipPolicySource>(['project_settings', 'chat_hold', 'subagent', 'person_grant', 'default']);

/**
 * The ship policy for the report: the newest `run.ship_policy` step (written by the run
 * preamble), narrowed by a hold the transcript still holds; a hold alone when no run
 * recorded a policy; null when neither exists.
 */
export function shipPolicyOfTrace(events: readonly BrainTraceEvent[], hold: PublishHold | null): ChatDiagnosticsData['shipPolicy'] {
  let recorded: { mode: unknown; source: unknown } | null = null;
  for (let i = events.length - 1; i >= 0; i--) {
    const e = events[i];
    if (e?.label === 'run.ship_policy' && e.args && typeof e.args === 'object') {
      recorded = e.args as { mode: unknown; source: unknown };
      break;
    }
  }
  const base = recorded && isShipMode(recorded.mode) && typeof recorded.source === 'string' && SHIP_SOURCES.has(recorded.source)
    ? shipPolicyOf(recorded.mode, recorded.source as ShipPolicySource)
    : null;
  if (!base && !hold) return null;
  // No recorded run: a hold alone narrows "something" — the default — to uncommitted.
  const p = narrowByHold(base ?? shipPolicyOf('commit', 'default'), hold);
  return { mode: p.mode, source: p.source, ...(p.hold ? { hold: p.hold } : {}) };
}

/**
 * Which account served this chat's turns, across EVERY turn (not just the last):
 * the one account when they all agree, `mixed` when they differ, null when no turn
 * recorded one. `accountUsedInTrace` is last-seen, which would let one own-key turn
 * speak for a chat whose other turns the shared pool paid for.
 */
function accountsAcrossTurns(events: readonly BrainTraceEvent[]): string | null {
  const seen = new Set<string>();
  for (const ev of events) {
    if (ev.category !== 'llm') continue;
    const a = accountUsedInTrace([ev]);
    if (a) seen.add(a);
  }
  return seen.size === 0 ? null : seen.size === 1 ? [...seen][0]! : 'mixed';
}

/** Run a best-effort read: never throws, never rejects, degrades to `fallback`. */
function safely<T>(read: (() => Promise<T>) | undefined, fallback: T): Promise<T> {
  if (!read) return Promise.resolve(fallback);
  try {
    return read().then((v) => v ?? fallback, () => fallback);
  } catch {
    return Promise.resolve(fallback);
  }
}

function ticketLinksOutsideSnapshot(
  events: readonly BrainTraceEvent[],
  tickets: NonNullable<ChatDiagnosticsData['tickets']>,
): NonNullable<ChatDiagnosticsData['ticketLinksOutsideSnapshot']> {
  const refs = new Set(tickets.map((ticket) => ticket.ref));
  const receipts = new Map<string, { ticketId: string; chatId: number }>();
  // One receipt per ticket/chat pair. Separate reads can have different freshness.
  for (const event of events) {
    if (event.category !== 'tool' || !isTicketWriteTool(event.label) || event.isError || isFailedToolResult(event.result)) continue;
    const link = toolResultRecord(toolResultRecord(event.result)?.chatLink);
    if (link?.linked !== true || typeof link.chatId !== 'number' || !Number.isSafeInteger(link.chatId)) continue;
    const { syncId } = entityIdsOf(event.result);
    if (!syncId || refs.has(String(syncId))) continue;
    const ticketId = String(syncId);
    receipts.set(`${link.chatId}/${ticketId}`, { ticketId, chatId: link.chatId });
  }
  return [...receipts.values()].slice(-5);
}

/** Normalize an Evermind head into the reported shape, dropping absent optionals so
 *  "not returned by this API version" stays distinguishable from "zero". */
function toEvermind(head: ChatDiagnosticsEvermindHead | null): ChatDiagnosticsEvermind | null {
  if (!head) return null;
  return {
    version: head.version,
    mode: head.mode,
    ...(head.inferenceEnabled != null ? { inferenceEnabled: head.inferenceEnabled } : {}),
    teacherModel: head.teacherModel ?? null,
    ...(head.contributions != null ? { contributions: head.contributions } : {}),
    ...(head.pending != null ? { pending: head.pending } : {}),
    lastLearnedAt: head.lastLearnedAt ?? null,
  };
}

/**
 * Assemble the diagnostics payload. Resolves — never rejects — so a caller can hand
 * the result straight to {@link formatChatDiagnostics} without a try/catch that would
 * only ever produce a worse report.
 */
export async function gatherChatDiagnostics(src: ChatDiagnosticsSources): Promise<ChatDiagnosticsData> {
  const [projectName, agents, tickets, runs, head, plan, apiVersion] = await Promise.all([
    safely(src.readProjectName, null as string | null),
    safely(src.readAgents, [] as Array<{ agentRef: string; role: string; name?: string; builtinKind?: string | null }>),
    safely(src.readTickets, null),
    safely(src.readRuns, null as ChatDiagnosticsRuns | null),
    safely(src.readEvermind, null as ChatDiagnosticsEvermindHead | null),
    safely(src.readPlan, null as ChatDiagnosticsPlanSnapshot | null),
    safely(src.readApiVersion, null as string | null),
  ]);

  // The learn-gate outcome for the NEWEST assistant turn: walk back, first one wins.
  // (`.reverse()` on the caller's array would mutate it — a diagnostics capture must
  // not reorder the transcript it is describing.)
  let lastLearn: ChatDiagnosticsData['lastLearn'] = null;
  const msgs = src.messages ?? [];
  for (let i = msgs.length - 1; i >= 0; i--) {
    const m = msgs[i];
    if (m.role === 'assistant' && m.evermindLearn) { lastLearn = m.evermindLearn; break; }
  }

  // What the model was ACTUALLY handed per turn, off the run's own trace — the number
  // the ceiling used to stand in for. Nulls when no turn in this run was measured.
  const exposure = src.trace ? toolExposureInTrace([...src.trace]) : null;
  // The MERGED trace (live steps + steps recovered from durable history) — what the
  // session did locally, any confirmed delivery and which account paid for its turns. Null when
  // there is nothing to measure, so "not measured" never reads as "none".
  const merged = traceWithPersistedSteps(msgs as unknown as BrainMessage[], src.trace ? [...src.trace] : []);
  const sessionShipped = merged.length ? sessionShippedInTrace(merged) : null;
  const servedBy = accountsAcrossTurns(merged);

  // The publish hold, re-derived from the PERSON's own user turns in the durable
  // transcript. The person-turn mark (`chatAsks.personTurns`) lives on the run's working
  // transcript, not the durable message rows, so here every `role: 'user'` turn is read as
  // the person's own words — EXCEPT a row whose metadata marks it injected (the editor's
  // Resume continuation, `injectedTurn.ts`), which the runtime never marks a person turn
  // either, so the report and the runtime agree. The runtime's `publishHold(convo)`
  // (person-marked only) stays the authority for actually refusing calls.
  const publishHold = publishHoldFromPersonTurns(
    msgs.filter((m) => m.role === 'user' && typeof m.content === 'string' && m.content.trim() && !isInjectedTurnMetadata(m.metadata))
        .map((m) => ({ text: m.content!.trim() })),
  );
  // The SHIP POLICY (PRD 48), read from the run record: the newest `run.ship_policy` step the
  // preamble wrote. A hold in force narrows it, exactly as the preamble does; with no recorded
  // run, a hold alone still reports `leave_uncommitted` from `chat_hold`.
  const shipPolicy = shipPolicyOfTrace(merged, publishHold);

  // A pending question is the one state that makes a FINISHED run still need the human:
  // the run settled terminally on an `ask_user`, so the chat is blocked on a decision
  // even though the run has ended. Derived from the transcript with the SAME selector
  // the chat surface uses to decide whether to render the pending-question bar, so the
  // report can never disagree with the UI about whether a question is outstanding.
  const pendingAsk = selectPendingAskUser(
    msgs
      .filter((m) => (m.role === 'assistant' || m.role === 'user') && typeof m.content === 'string')
      .map((m) => ({ id: 0, role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content as string })),
  );
  const pendingQuestions = pendingAsk ? [{ text: pendingAsk.payload.question }] : [];

  const account: ChatDiagnosticsAccount = {
    plan: plan?.plan.effective ?? null,
    billingStatus: plan?.plan.billingStatus ?? null,
    periodStart: plan?.period.start ?? null,
    resetsAt: plan?.period.resetsAt ?? null,
    meters: plan?.meters ?? [],
    model: src.model ?? null,
    // Funding was one of the four fields the probe silently dropped, which is how a
    // probe report could look clean about a chat whose model the plan cannot fund.
    modelFunding: src.modelSurface ? classifyModelFunding(src.model, src.modelSurface) : null,
    ...(src.modelSurface?.canUsePremiumModels != null ? { canUsePremiumModels: src.modelSurface.canUsePremiumModels } : {}),
    ...(src.modelSurface?.data ? { planModelCount: src.modelSurface.data.length } : {}),
    byoProviders: src.modelSurface?.byo?.providers ?? [],
    servedBy,
    extensionVersion: src.uiVersion ?? null,
    baseUrl: src.baseUrl ?? null,
  };

  return {
    surface: src.surface,
    chatId: src.chatId ?? null,
    chatTitle: src.chatTitle ?? null,
    history: {
      // What this view has LOADED (a web chat holds a tail window), split so the count
      // of the conversation is not inflated by the run's steps.
      messages: msgs.filter((m) => !isStepMessage(m)).length,
      steps: msgs.filter(isStepMessage).length,
      ...(merged.length ? { traceSteps: merged.length } : {}),
      location: src.historyLocation?.trim() || null,
    },
    chatVisibility: src.chatVisibility ?? null,
    mode: src.mode ?? null,
    projectId: src.projectId ?? null,
    projectName: projectName ?? src.projectName ?? null,
    selectedProjectId: src.selectedProjectId ?? null,
    selectedProjectName: src.selectedProjectName ?? null,
    tenantId: src.tenantId ?? null,
    userId: src.userId ?? null,
    workspaceTenantId: src.workspaceTenantId ?? null,
    role: src.role ?? null,
    evermind: toEvermind(head),
    lastLearn,
    shipPolicy,
    pendingQuestions,
    agents: agents.map((a) => ({
      agentRef: a.agentRef,
      role: a.role,
      ...(a.name ? { name: a.name } : {}),
      ...(a.builtinKind != null ? { builtinKind: a.builtinKind } : {}),
    })),
    runs,
    sessionShipped,
    sessionWork: merged.length ? sessionWorkInTrace(merged) : null,
    ticketSnapshotAvailable: tickets !== null,
    ...(tickets ? { ticketLinksOutsideSnapshot: ticketLinksOutsideSnapshot(merged, tickets) } : {}),
    tickets: (tickets ?? []).map((tk) => ({ kind: tk.kind, ref: tk.ref, label: tk.label, linkType: tk.linkType, status: tk.status })),
    account,
    spend: src.spend ?? null,
    tools: src.tools
      ? {
          count: src.tools.count,
          error: src.tools.error ?? null,
          loading: src.tools.loading ?? false,
          advertisedMin: exposure?.min ?? null,
          advertisedLastTurn: exposure?.lastTurn ?? null,
        }
      : null,
    versions: {
      ui: src.uiVersion ?? null,
      api: apiVersion,
      uiBuildId: src.uiBuildId ?? null,
      uiBuiltAt: src.uiBuiltAt ?? null,
      webviewBuildId: src.webviewBuildId ?? null,
      webviewBuiltAt: src.webviewBuiltAt ?? null,
      posixShell: src.posixShell ?? null,
    },
  };
}
